import{_ as t,o as a,c as r,a3 as c}from"./chunks/framework.DAK02U1-.js";const m=JSON.parse('{"title":"Patches","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Patches | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/xclang/design/patches"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"en_US"}],["link",{"rel":"canonical","href":"https://docs.clice.io/xclang/design/patches"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/xclang/design/patches"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/xclang/design/patches"}]]},"headers":[],"relativePath":"xclang/design/patches.md","filePath":"en/xclang/design/patches.md","lastUpdated":1791227177000}'),o={name:"xclang/design/patches.md"};function n(i,e,s,l,d,h){return a(),r("div",null,[...e[0]||(e[0]=[c('<h1 id="patches" tabindex="-1">Patches <a class="header-anchor" href="#patches" aria-label="Permalink to &quot;Patches&quot;">​</a></h1><p>xclang builds LLVM&#39;s release source with the changes in <a href="https://github.com/clice-io/xclang/tree/main/patches" target="_blank" rel="noreferrer"><code>patches/</code></a>, one directory each: the patch and a README on what it changes, why, how it was checked, and its state upstream. They are applied in the order of the directories right after the source is unpacked, so a tag&#39;s workflow, run again, builds the same thing; libclang&#39;s manifest lists them (<code>XCLANG_PATCHES</code> in <code>lib/cmake/xclang/libclang.cmake</code>).</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><a href="https://github.com/clice-io/xclang/blob/main/patches/0001-sema-partial-ordering-depth/README.md" target="_blank" rel="noreferrer"><code>0001-sema-partial-ordering-depth</code></a></td><td>partial ordering deduces at the templates&#39; own depth: code completion in a class template no longer crashes clang (<a href="https://github.com/clice-io/clice/issues/701" target="_blank" rel="noreferrer">clice#701</a>)</td></tr><tr><td><a href="https://github.com/clice-io/xclang/blob/main/patches/0002-completion-unresolved-member-base/README.md" target="_blank" rel="noreferrer"><code>0002-completion-unresolved-member-base</code></a></td><td>member-access completion reports its context when Sema finds no class for the base</td></tr><tr><td><a href="https://github.com/clice-io/xclang/blob/main/patches/0003-completion-context-base-expr/README.md" target="_blank" rel="noreferrer"><code>0003-completion-context-base-expr</code></a></td><td><code>CodeCompletionContext::getBaseExpr</code>, the member base as written</td></tr><tr><td><a href="https://github.com/clice-io/xclang/blob/main/patches/0004-windows-driver-setup-api-mingw/README.md" target="_blank" rel="noreferrer"><code>0004-windows-driver-setup-api-mingw</code></a></td><td>the MinGW-built clang finds Visual Studio 2017 and later through the Setup API, like the MSVC-built one (<a href="https://github.com/clice-io/clice/issues/714" target="_blank" rel="noreferrer">clice#714</a>)</td></tr><tr><td><a href="https://github.com/clice-io/xclang/blob/main/patches/0006-libcxx-format-buffer-full/README.md" target="_blank" rel="noreferrer"><code>0006-libcxx-format-buffer-full</code></a></td><td><code>std::format_to</code> into a container no longer writes past its 256-code-unit stack buffer after an argument whose length is a multiple of 256</td></tr><tr><td><a href="https://github.com/clice-io/xclang/blob/main/patches/0007-lld-macho-empty-section-unwind/README.md" target="_blank" rel="noreferrer"><code>0007-lld-macho-empty-section-unwind</code></a></td><td>ld64.lld keeps a function&#39;s unwind entry when an empty section&#39;s symbol shares its address: ThinLTO programs linked by one clang command catch their exceptions on arm64 macOS</td></tr><tr><td><a href="https://github.com/clice-io/xclang/blob/main/patches/0008-preprocessed-raw-string-lines/README.md" target="_blank" rel="noreferrer"><code>0008-preprocessed-raw-string-lines</code></a></td><td><code>clang -E</code> writes a raw string literal&#39;s CRLF line breaks as <code>\\n</code>, what they mean, and counts its lines: its output, compiled (build caches such as xmake&#39;s), gives the same strings and line numbers</td></tr><tr><td><a href="https://github.com/clice-io/xclang/blob/main/patches/0009-textapi-arm64e-x1/README.md" target="_blank" rel="noreferrer"><code>0009-textapi-arm64e-x1</code></a></td><td>ld64.lld reads the macOS 27 SDK&#39;s <code>.tbd</code> stubs, which list <code>arm64e.x1</code>: macOS programs link against Xcode 27&#39;s SDK (release/23.x&#39;s backport, in 23.1.3)</td></tr></tbody></table><p>0005 (ASan&#39;s container checks in libc++&#39;s ODR signature) was in 23.1.2.3 and 23.1.2.4; libc++&#39;s ASan build replaced it in 23.1.2.5. <a href="https://github.com/clice-io/xclang/blob/main/CHANGELOG.md" target="_blank" rel="noreferrer">CHANGELOG.md</a> has which release took which patch.</p>',4)])])}const g=t(o,[["render",n]]);export{m as __pageData,g as default};
